#include<bits/stdc++.h>
using namespace std;
int main(){const int T=7680,F=256,N=7936;vector<array<int8_t,16>> old(3840),V(T);ifstream a("research/mixed_tier17_eval_subgroup_20261105/cache/mixed17_eval4_orbits.bin",ios::binary);a.read((char*)old.data(),3840*16);vector<uint16_t> H(16),orig(128),K;ifstream b("research/mixed_tier17_eval_subgroup_20261105/cache/mixed17_eval4_group.bin",ios::binary);b.read((char*)H.data(),32);ifstream f("research/mixed_tier17_eval_subgroup_20261105/cache/mixed17_eval4_flat_reps.bin",ios::binary);f.read((char*)orig.data(),256);if(!a||!b||!f)return 2;uint16_t h0=0;for(auto h:H)if(h&2){if(!h0)h0=h;}else K.push_back(h);if(K.size()!=8||!h0)return 3;for(int i=0;i<3840;i++)for(int q=0;q<2;q++)for(int j=0;j<16;j++)V[2*i+q][j]=old[i][j]*((q&&(h0>>j&1))?-1:1);vector<uint16_t> flat(F);for(int i=0;i<128;i++){flat[2*i]=orig[i];flat[2*i+1]=orig[i]^h0;}ofstream out("research/mixed_tier17_order8_20261105/cache/graph_edges.bin",ios::binary);long long count=0;auto add=[&](int i,int j){out.write((char*)&i,4);out.write((char*)&j,4);count++;};for(int i=0;i<F;i++)for(int j=i+1;j<F;j++){bool bad=false;for(auto h:K)if(__builtin_popcount((unsigned)(flat[i]^flat[j]^h))<6){bad=true;break;}if(bad)add(i,j);}for(int i=0;i<T;i++)for(int j=0;j<F;j++){bool bad=false;for(auto h:K){int d=0,w=flat[j]^h;for(int k=0;k<16;k++)d+=V[i][k]*((w>>k&1)?-1:1);if(d>8){bad=true;break;}}if(bad)add(F+i,j);}for(int i=0;i<T;i++){for(int j=i+1;j<T;j++){bool bad=false;for(auto h:K){int d=0;for(int k=0;k<16;k++)d+=int(V[i][k])*int(V[j][k])*((h>>k&1)?-1:1);if(d>8){bad=true;break;}}if(bad)add(F+i,F+j);}if(i%500==0)cerr<<"tier "<<i<<" edges "<<count<<endl;}cout<<"vertices "<<N<<" edges "<<count<<endl;}
